package main

import (
	"fmt"
)

func main() {
	var n, ans int
	fmt.Scanln(&n)

	a := make([]int, n)
	x := make([]interface{}, n)
	for i := range a {
		x[i] = &a[i]
	}
	fmt.Scanln(x...)

	for i := 0; i < n; i++ {
		ans += a[i]
	}
	ans /= n
	fmt.Println(ans)
}
